1	// Red-first coverage for swift-toolchain-gate.
2	//
3	// The comment cases are the ones worth pinning in both directions. A script that
4	// gets this right tends to document the trap directly above the gated call, so a
5	// scan that does not strip `#` comments flags the warning instead of a violation;
6	// and a commented-out gate must not be credited as a gate either.
7	import { test } from 'node:test';
8	import assert from 'node:assert/strict';
9	import { makeRepo, cleanup } from '../../../engine-tests/helpers.mjs';
10	import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
11	import toolchainGate from '../worldRules/swift-toolchain-gate.mjs';
12	
13	const runOn = (files) => {
14	  const root = makeRepo({ changed: files });
15	  try {
16	    return toolchainGate.run(buildContext({ root, mode: 'all' }));
17	  } finally { cleanup(root); }
18	};
19	
20	const quiet = (files) => {
21	  const findings = runOn(files);
22	  assert.deepEqual(findings, [], `expected silence, got ${JSON.stringify(findings, null, 2)}`);
23	};
24	
25	test('flags an ungated Swift probe in a shell script', () => {
26	  const findings = runOn({
27	    'scripts/diagnose.sh': `#!/bin/bash
28	if command -v swift >/dev/null 2>&1; then
29	  swift run Diagnose
30	fi
31	`,
32	  });
33	  assert.equal(findings.length, 1);
34	  assert.equal(findings[0].rule, 'swift-toolchain-gate');
35	  assert.equal(findings[0].severity, 'blocking');
36	  assert.equal(findings[0].file, 'scripts/diagnose.sh');
37	  assert.equal(findings[0].line, 2);
38	  assert.match(findings[0].fix, /xcode-select -p/);
39	});
40	
41	test('quiet when xcode-select gates the probe on the same line', () => {
42	  quiet({
43	    'scripts/diagnose.sh': `#!/bin/bash
44	if xcode-select -p >/dev/null 2>&1 && command -v swift >/dev/null 2>&1; then
45	  swift run Diagnose
46	fi
47	`,
48	  });
49	});
50	
51	// Same-or-earlier, not same-line: a gate several lines up is as good as an `&&`.
52	test('quiet when the gate sits earlier in the script', () => {
53	  quiet({
54	    'scripts/diagnose.sh': `#!/bin/bash
55	xcode-select -p >/dev/null 2>&1 || { echo "no developer tools; skipping"; exit 0; }
56	command -v swift >/dev/null 2>&1 && swift run Diagnose
57	`,
58	  });
59	});
60	
61	test('quiet on a comment that merely documents the trap', () => {
62	  quiet({
63	    'scripts/diagnose.sh': `#!/bin/bash
64	# NOTE: command -v swift is NOT a usable test — /usr/bin/swift is a stub.
65	xcode-select -p >/dev/null 2>&1 || exit 0
66	`,
67	  });
68	});
69	
70	test('a commented-out gate does not count as a gate', () => {
71	  const findings = runOn({
72	    'scripts/diagnose.sh': `#!/bin/bash
73	# xcode-select -p >/dev/null 2>&1 || exit 0
74	command -v swift >/dev/null 2>&1 && swift run Diagnose
75	`,
76	  });
77	  assert.equal(findings.length, 1);
78	  assert.equal(findings[0].line, 3);
79	});
80	
81	test('folds a backslash continuation and reports the line the command started on', () => {
82	  const findings = runOn({
83	    'scripts/diagnose.sh': `#!/bin/bash
84	command -v \\
85	  swift >/dev/null 2>&1 && swift run Diagnose
86	`,
87	  });
88	  assert.equal(findings.length, 1);
89	  assert.equal(findings[0].line, 2);
90	});
91	
92	// `swiftlint` and `swift-format` are other tools that merely start with the word.
93	test('quiet on a probe for a differently-named tool', () => {
94	  quiet({
95	    'scripts/lint.sh': `#!/bin/bash
96	command -v swiftlint >/dev/null 2>&1 && swiftlint
97	`,
98	  });
99	});
100	
101	test('workflow YAML is in scope', () => {
102	  const findings = runOn({
103	    '.github/workflows/diagnose.yml': `name: Diagnose
104	jobs:
105	  run:
106	    steps:
107	      - run: command -v swift && swift build
108	`,
109	  });
110	  assert.equal(findings.length, 1);
111	  assert.equal(findings[0].file, '.github/workflows/diagnose.yml');
112	});
